            except Exception as e:
                raise TomlParseError(str(e))
        else:
            out_parts.append(part)
    return out_parts


def parse_basic_string(token: str) -> str:
    try:
        return json.loads(token)
    except Exception as e:
        raise TomlParseError(str(e))


def parse_literal_string(token: str) -> str:
    if not (token.startswith("'") and token.endswith("'")):
        raise TomlParseError("invalid literal string")
    return token[1:-1]


def parse_array(token: str) -> list[Any]:
    if not (token.startswith('[') and token.endswith(']')):
        raise TomlParseError("invalid array")
    body = token[1:-1]
    vals: list[Any] = []
    i = 0
    n = len(body)
    while i < n:
        while i < n and (body[i].isspace() or body[i] == ','):
            i += 1
        if i >= n:
            break
        if body.startswith("'''", i):
            j = body.find("'''", i + 3)
            if j < 0:
                raise TomlParseError("unterminated string")
            val = body[i+3:j]
            if val.startswith('\r\n'):
                val = val[2:]
            elif val.startswith('\n'):
                val = val[1:]
            vals.append(val)
            i = j + 3
        elif body[i] == "'":
            j = body.find("'", i + 1)
            if j < 0:
                raise TomlParseError("unterminated string")
            vals.append(body[i+1:j])
            i = j + 1
        elif body[i] == '"':
            j = i + 1
            esc = False
            while j < n:
                if esc:
                    esc = False
                elif body[j] == "\\":
                    esc = True
                elif body[j] == '"':
                    break
                j += 1
            if j >= n:
                raise TomlParseError("unterminated string")
            vals.append(parse_basic_string(body[i:j+1]))
            i = j + 1
        else:
            j = i
            while j < n and body[j] not in ',\n':
                j += 1
            vals.append(parse_value(body[i:j].strip()))
            i = j
    return vals


def parse_value(token: str) -> Any:
    token = strip_comment(token).strip()
    if token == "":
        return ""
    if token.startswith("'''") and token.endswith("'''") and len(token) >= 6:
        val = token[3:-3]
        if val.startswith('\r\n'):
            val = val[2:]
        elif val.startswith('\n'):
            val = val[1:]
        return val
    if token.startswith("'"):
        return parse_literal_string(token)
    if token.startswith('"'):
        return parse_basic_string(token)
    if token.startswith('['):
        return parse_array(token)
    if re.fullmatch(r"[+-]?\d+", token):
        return int(token)
    if token == "true":
        return True
    if token == "false":
        return False
    raise TomlParseError(f"unsupported value {token!r}")


def loads_toml_subset(text: str) -> dict[str, Any]:
    data: dict[str, Any] = {}
    current: Optional[dict[str, Any]] = data
    lines = text.splitlines(keepends=True)
    i = 0
    while i < len(lines):
        raw = lines[i]
        stripped = strip_comment(raw).strip()
        if stripped == "":
            i += 1
            continue
        if stripped.startswith('[') and stripped.endswith(']') and not stripped.startswith('[['):
            parts = split_dotted(stripped[1:-1])
            if not parts:
                raise TomlParseError("empty table")
            if parts[0] == 'scripts':
                scripts = data.setdefault('scripts', {})
                if len(parts) == 1:
                    current = scripts
                else:
                    alias = '.'.join(parts[1:]) if len(parts) > 2 else parts[1]
                    table = scripts.setdefault(alias, {})
                    current = table
            elif parts[0] == 'default' and len(parts) == 1:
                current = data.setdefault('default', {})
            else:
                table = data
                for part in parts:
                    table = table.setdefault(part, {})
                current = table
            i += 1
            continue
        if '=' not in raw:
            raise TomlParseError("expected key/value")
        key, after = raw.split('=', 1)
        key = key.strip()
        valtext = after.lstrip()
        if valtext.startswith("'''"):
            rest = valtext[3:]
            collected = rest
            while "'''" not in collected:
                i += 1
                if i >= len(lines):
                    raise TomlParseError("unterminated string")
                collected += lines[i]
            pos = collected.find("'''")
            val = collected[:pos]
            if val.startswith('\r\n'):
                val = val[2:]
            elif val.startswith('\n'):
                val = val[1:]
            value = val
        else:
            if valtext.strip().startswith('[') and ']' not in strip_comment(valtext):
                collected = valtext
                while ']' not in strip_comment(collected):
                    i += 1
                    if i >= len(lines):
                        raise TomlParseError("unterminated array")
                    collected += lines[i]
                value = parse_value(collected)
            else:
                value = parse_value(valtext)
        if current is None:
            current = data
        current[key] = value
        i += 1
    return data
